return {api_version=1,id="EX1_309",name="Siphon Soul",text="Destroy a minion. Restore #3 Health to your hero.",set="EXPERT1",type="spell",class="warlock",rarity="rare",spell_school="shadow",cost=4,target_mode="required",targets=function(ctx)return ctx:minions()end,on_play=function(ctx,self,target)local p=ctx:controller(self);ctx:destroy(target);ctx:heal(ctx:player(p).hero,3)end}
